package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.view.accessibility.*;import android.accessibilityservice.AccessibilityServiceInfo;import android.widget.*;import android.graphics.Rect;import android.os.*;import java.util.*;import org.json.*;
/** Actual injected touch only: no scrollTo/accessibility scroll or keyboard dismissal. */
final class VertexScrollChecks {
 final MapAndroidChecks m;final VertexRotationChecks p;final ManagerVisualChecks v;final ManagerRotationChecks r;
 VertexScrollChecks(MapAndroidChecks m){this.m=m;p=new VertexRotationChecks(m);v=p.v;r=p.r;}
 ScrollView pane(){View n=p.field(m.activeDialogRoot());while(n!=null&&!(n instanceof ScrollView))n=n.getParent() instanceof View?(View)n.getParent():null;if(n==null)throw new AssertionError("raw form ScrollView");return (ScrollView)n;}
 TextView message(String kind){if(kind.equals("invalid"))return p.validation(m.activeDialogRoot());return text(m.activeDialogRoot(),"Геометрия или исходный ввод изменились.");}
 TextView text(View n,String prefix){if(n instanceof TextView&&((TextView)n).getText().toString().startsWith(prefix))return (TextView)n;if(n instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)n;for(int i=0;i<g.getChildCount();i++){TextView t=text(g.getChildAt(i),prefix);if(t!=null)return t;}}return null;}
 Rect box(View n){int[] xy=new int[2];n.getLocationOnScreen(xy);return new Rect(xy[0],xy[1],xy[0]+n.getWidth(),xy[1]+n.getHeight());}
 Rect frame(){Rect f=new Rect();m.activity.getWindow().getDecorView().getWindowVisibleDisplayFrame(f);return f;}
 Rect viewport(){Rect b=box(pane());b.intersect(frame());return b;}
 void actions()throws Exception{m.check(v.imeWindows().length()>0,"IME stays open throughout touch-scroll");final boolean[] ok={true};m.runOnMainSync(()->{Rect f=frame();for(String label:new String[]{"Применить","Отмена"}){View b=v.button(m.activeDialogRoot(),label);ok[0]&=b!=null&&b.isShown()&&f.contains(box(b));}});m.check(ok[0],"explicit Apply/Cancel remain physically inside Activity frame during scroll");}
 JSONObject observe(String kind,BitSet covered)throws Exception{final JSONObject o=new JSONObject();final RuntimeException[] error={null};m.runOnMainSync(()->{try{ScrollView s=pane();TextView t=message(kind);if(t==null||t.getLayout()==null)throw new AssertionError("long message layout");Rect clip=viewport(),bounds=box(t);JSONArray lines=new JSONArray();int count=t.getLayout().getLineCount();for(int i=0;i<count;i++){int top=bounds.top+t.getTotalPaddingTop()+t.getLayout().getLineTop(i)-t.getScrollY(),bottom=bounds.top+t.getTotalPaddingTop()+t.getLayout().getLineBottom(i)-t.getScrollY();boolean full=t.isShown()&&top>=clip.top&&bottom<=clip.bottom&&bounds.left>=clip.left&&bounds.right<=clip.right;if(full)covered.set(i);lines.put(new JSONObject().put("line",i).put("top",top).put("bottom",bottom).put("full",full));}o.put("kind",kind);o.put("message",t.getText().toString());o.put("lines",lines);o.put("covered",covered.toString());o.put("lineCount",count);o.put("scrollY",s.getScrollY());o.put("viewport",clip.flattenToString());o.put("activityFrame",frame().flattenToString());o.put("messageBounds",bounds.flattenToString());}catch(Exception e){error[0]=new RuntimeException(e);}});if(error[0]!=null)throw error[0];o.put("raw",p.state());o.put("ime",v.imeWindows());v.emit("VERTEX_SCROLL "+o.toString());return o;}
 void swipe(boolean forward)throws Exception{final Rect[] b={null};m.runOnMainSync(()->b[0]=viewport());Rect rect=b[0];m.check(rect.height()>16&&rect.width()>48,"physical ScrollView touch area above IME");float x=rect.right-24,y0=forward?rect.bottom-2:rect.top+2,y1=forward?rect.top+2:rect.bottom-2;long down=SystemClock.uptimeMillis();for(int i=0;i<=12;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==12?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y0+(y1-y0)*i/12,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);m.check(m.getUiAutomation().injectInputEvent(e,true),"real scroll touch accepted "+i);e.recycle();Thread.sleep(25);}m.waitForIdleSync();Thread.sleep(250);}
 void tap(String label)throws Exception{final Rect[] rect={null};m.runOnMainSync(()->rect[0]=box(v.button(m.activeDialogRoot(),label)));long down=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,rect[0].exactCenterX(),rect[0].exactCenterY(),0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);m.check(m.getUiAutomation().injectInputEvent(e,true),"physical explicit action "+label);e.recycle();Thread.sleep(80);}m.waitForIdleSync();Thread.sleep(250);}
 void scenario(Object store,String kind)throws Exception{long id=p.fixture.insert(store);try{Object original=r.load(store,id);byte[] xml=r.xml(original);Map<String,byte[]> assets=new HashMap<>(m.assets(original));p.open(id,p.mainText);if(kind.equals("invalid")){m.inputs("91 0");m.click("Применить");m.runOnMainSync(()->p.field(m.activeDialogRoot()).setSelection(1,3));}else if(kind.equals("stale"))p.changeGeometry(store,id,false);byte[] current=r.xml(r.load(store,id));p.actualLand();v.keyboard();p.identity(id,"point");JSONObject raw=p.state();m.check(raw.getInt("start")==1&&raw.getInt("end")==3,"scroll exact selection fixture");m.check(!raw.getString("error").isEmpty()==kind.equals("invalid"),"scroll exact validation fixture");p.snapshot("vertex-scroll-"+kind+"-field",true);BitSet covered=new BitSet();JSONObject first=observe(kind,covered);final int[] h={0};m.runOnMainSync(()->h[0]=frame().height());v.emit("VERTEX_SCROLL_PRECONDITION kind="+kind+" frameHeight="+h[0]+" expected=82 api="+Build.VERSION.SDK_INT);if(Build.VERSION.SDK_INT==35)m.check(h[0]==82,"API35 tight82px landscape with real IME");int count=first.getInt("lineCount"),initial=first.getInt("scrollY");boolean moved=false;boolean forward=kind.equals("invalid");for(int i=0;i<8;i++){int previous=covered.cardinality();swipe(i<4?forward:!forward);actions();p.sameRaw(raw);JSONObject state=observe(kind,covered);moved|=state.getInt("scrollY")!=initial;if(covered.cardinality()>previous)p.snapshot("vertex-scroll-"+kind+"-line-"+(char)('a'+i));if(covered.cardinality()==count)break;}
 p.snapshot("vertex-scroll-"+kind+"-message");actions();p.sameRaw(raw);m.check(covered.cardinality()==count,"every complete inline message line physically read via real touch while IME remains open: "+covered+"/"+count);if(Build.VERSION.SDK_INT==35)m.check(moved,"touch actually changes ScrollView position on API35");for(int i=0;i<8;i++){final boolean[] available={false};m.runOnMainSync(()->{EditText f=p.field(m.activeDialogRoot());Rect b=box(f),clip=viewport();available[0]=f.isShown()&&Math.min(b.bottom,clip.bottom)-Math.max(b.top,clip.top)>=f.getLineHeight();});if(available[0])break;swipe(!forward);actions();v.emit("VERTEX_SCROLL_RETURN "+p.state().toString());p.sameRaw(raw);}p.snapshot("vertex-scroll-"+kind+"-return",true);p.sameRaw(raw);p.identity(id,"point");m.check(!p.enabled()==kind.equals("stale"),"original token still guards Apply after scrolling");if(kind.equals("invalid")){tap("Применить");p.sameRaw(raw);}m.check(m.geometryInput().equals(p.mainText)&&Arrays.equals(current,r.xml(r.load(store,id))),"touch and explicit rejected Apply never alter main/KML");tap("Отмена");m.check(m.geometryInput().equals(p.mainText)&&Arrays.equals(current,r.xml(r.load(store,id))),"scroll Cancel preserves main/KML");r.sameAssets(r.load(store,id),assets);p.ghost();v.emit("VERTEX_SCROLL_RESULT kind="+kind+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(String kind:new String[]{"invalid","stale"})scenario(store,kind);m.check(m.requests.get()==requests,"touch-scroll stays local");}finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}}
}
